"""Offline paired clue experiment. Run with python3 -m hanabi.clue_probe."""
from copy import deepcopy
import json

from .arena import MAX_TURNS
from .bots import choose
from .game import Game

DEAL = 70696
HORIZON = 3  # Plies AFTER the intervention: receiver, giver, receiver.


def hint(kind, value):
    return {"type": "hint", "kind": kind, "value": value}


def snapshot(prior_red):
    """A selected legal replay, not a prefix generated by either player policy."""
    game = Game(DEAL)
    one, five = hint("rank", 1), hint("rank", 5)
    for move in (one, {"type": "play", "index": 4}, {"type": "play", "index": 2},
                 {"type": "play", "index": 4}, {"type": "discard", "index": 0},
                 one, five, one, five, one, hint("color", "red") if prior_red else five, one):
        game.apply(move)
    return game


def branch(source, intervention, *, target_index=0):
    """Force one legal action, then use unmodified, deterministic Lantern for both seats."""
    game = deepcopy(source)
    receiver = 1 - game.current
    game.apply(intervention)
    view = game.view(game.current)
    opening = view["history"][-1]
    first = None
    status = "in_hand"
    horizon = None
    plies = 0
    while not game.over:
        if plies >= MAX_TURNS:
            raise RuntimeError("Clue branch exceeded arena turn limit")
        game.apply(choose(view, "lantern"))
        view = game.view(game.current)
        event = view["history"][-1]
        plies += 1
        if plies == 1:
            first = event
        # Follow the original physical slot by public removals. A replacement
        # or another card of the same rank/color must never count as the target.
        if status == "in_hand" and event["player"] == receiver and event["type"] != "hint":
            if event["index"] < target_index:
                target_index -= 1
            elif event["index"] == target_index:
                status = ("discarded" if event["type"] == "discard" else
                          "played" if event["success"] else "misplayed")
        if plies == HORIZON:
            horizon = status
    return {"intervention": opening, "next_receiver_event": first,
            "horizon_plies": min(plies, HORIZON), "target_at_horizon": horizon or status,
            "target_at_end": status, "end": game.end, "strict_score": game.score}


def probe():
    cases = []
    for prior_red in (False, True):
        game = snapshot(prior_red)
        giver = game.view(game.current)
        natural = choose(giver, "lantern")
        actions = [a for a in giver["legal"] if a["type"] == "hint"]
        if natural not in actions:
            actions.append(natural)
        cases.append({"prior_red": prior_red, "unforced_action": natural,
                      "branches": [branch(game, move) for move in actions]})
    return {"format": "hanabi-clue-probe-v1", "deal": DEAL, "policy": "lantern",
            "target": {"receiver": 1, "starting_index": 0, "color": "red", "rank": 3},
            "horizon_plies_after_intervention": HORIZON, "cases": cases}


if __name__ == "__main__":
    print(json.dumps(probe(), indent=2))
